import{_ as t,o as i,c as e,ag as o}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"李笑来《好的家庭教育》核心观点","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/family-education/xiaolai-family-education.md","filePath":"topics/family-education/xiaolai-family-education.md"}'),r={name:"topics/family-education/xiaolai-family-education.md"};function l(n,a,h,s,d,u){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="李笑来《好的家庭教育》核心观点" tabindex="-1">李笑来《好的家庭教育》核心观点 <a class="header-anchor" href="#李笑来《好的家庭教育》核心观点" aria-label="Permalink to &quot;李笑来《好的家庭教育》核心观点&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>视频介绍李笑来所著《好的家庭教育》——并非传统&quot;鸡娃&quot;指南，而是超越育儿技巧的人生底层逻辑读物，核心是重塑赚钱、决策、个人成长等方面的认知。</p><hr><h2 id="核心观念" tabindex="-1">核心观念 <a class="header-anchor" href="#核心观念" aria-label="Permalink to &quot;核心观念&quot;">​</a></h2><h3 id="_1-判断力-其他一切能力" tabindex="-1">1. 判断力 &gt; 其他一切能力 <a class="header-anchor" href="#_1-判断力-其他一切能力" aria-label="Permalink to &quot;1. 判断力 &gt; 其他一切能力&quot;">​</a></h3><p>决定命运的关键是<strong>判断力</strong>，比勤奋、技能、资源都重要。判断力决定了选择的质量，选择的质量决定了结果。</p><h3 id="_2-夫妻关系是家庭的基石" tabindex="-1">2. 夫妻关系是家庭的基石 <a class="header-anchor" href="#_2-夫妻关系是家庭的基石" aria-label="Permalink to &quot;2. 夫妻关系是家庭的基石&quot;">​</a></h3><p>家庭中<strong>唯一的非血缘关系</strong>是夫妻关系，这是一切家庭问题的核心。夫妻关系处理好了，亲子关系自然顺。</p><h3 id="_3-孩子-不懂事-是大人的问题" tabindex="-1">3. 孩子&quot;不懂事&quot;是大人的问题 <a class="header-anchor" href="#_3-孩子-不懂事-是大人的问题" aria-label="Permalink to &quot;3. 孩子&quot;不懂事&quot;是大人的问题&quot;">​</a></h3><p>孩子的问题往往是大人的教育方式导致的，不应简单归咎于孩子。</p><h3 id="_4-正确的金钱观" tabindex="-1">4. 正确的金钱观 <a class="header-anchor" href="#_4-正确的金钱观" aria-label="Permalink to &quot;4. 正确的金钱观&quot;">​</a></h3><ul><li>不应妖魔化钱，要崇尚&quot;经济能力&quot;</li><li>金钱是工具，不是目的</li><li>理解金钱的工具性价值，才能真正驾驭它</li></ul><h3 id="_5-个人成长-专注比成绩更重要" tabindex="-1">5. 个人成长：专注比成绩更重要 <a class="header-anchor" href="#_5-个人成长-专注比成绩更重要" aria-label="Permalink to &quot;5. 个人成长：专注比成绩更重要&quot;">​</a></h3><p>专注是比学习成绩更底层的能力。专注力培养好了，成绩是自然结果。</p><h3 id="_6-女性也应注重体能训练" tabindex="-1">6. 女性也应注重体能训练 <a class="header-anchor" href="#_6-女性也应注重体能训练" aria-label="Permalink to &quot;6. 女性也应注重体能训练&quot;">​</a></h3><p>无论男女，体能是长期生活挑战的基础支撑，女生同样需要。</p><h3 id="_7-终身自我迭代" tabindex="-1">7. 终身自我迭代 <a class="header-anchor" href="#_7-终身自我迭代" aria-label="Permalink to &quot;7. 终身自我迭代&quot;">​</a></h3><p>成年人也应持续学习，&quot;重养自己一遍&quot;——把自己重新养一遍，实现终身成长。</p><hr><h2 id="知识点速记" tabindex="-1">知识点速记 <a class="header-anchor" href="#知识点速记" aria-label="Permalink to &quot;知识点速记&quot;">​</a></h2><ul><li><strong>判断力第一</strong>：决定命运的核心能力</li><li><strong>夫妻关系 &gt; 亲子关系</strong>：家庭基石</li><li><strong>专注力</strong>：比成绩更基础的能力</li><li><strong>经济能力</strong>：不妖魔化钱，理解工具性价值</li><li><strong>重养自己</strong>：成年人的终身成长路径</li></ul><hr><h2 id="相关话题" tabindex="-1">相关话题 <a class="header-anchor" href="#相关话题" aria-label="Permalink to &quot;相关话题&quot;">​</a></h2><ul><li>[[self-motivation]]：内在动力与自我驱动</li><li>[[ethics]]：功利主义与财富观</li><li>[[infant-care]]：家庭教育实践层</li></ul>',25)])])}const q=t(r,[["render",l]]);export{_ as __pageData,q as default};
